<script setup lang="ts">
import {ref,onMounted,onActivated,onDeactivated,onBeforeUnmount} from 'vue'
import {ElMessageBox} from 'element-plus'
import {dsm,DsmClient} from '../api/dsm'
import {backupResult,displayTime} from '../utils/driveBackup'
import {createHyperBackup,hyperId,hyperState,hyperShares,hyperParams,hyperError,type HyperAction,type HyperDraft} from '../utils/hyperBackup'
import FolderPicker from './FolderPicker.vue'
const pending=ref<Record<string,string>>({})
function signature(raw:any){return JSON.stringify([raw?.state,raw?.status,raw?.last_bkp_time,raw?.last_bkp_result])}
const rows=ref<any[]>([]),loading=ref(false),error=ref(''),notice=ref(''),available=ref(false),creating=ref(false),submitting=ref(false),actionBusy=ref(''),picker=ref(false),shares=ref<Array<{name:string}>>([]),detail=ref<any>(null),journal=ref<any>(null)
const draft=ref<HyperDraft>({name:'NAS 文件备份',share:'',directory:'SynoLink-backup',sources:[],compress:true})
const phaseLabels:Record<string,string>={'repository-submitting':'仓库创建请求已提交','repository-created':'仓库已创建','task-submitting':'任务创建请求已提交',done:'任务已创建'}
const labels:Record<HyperAction,string>={backup:'立即备份',cancel:'取消备份',suspend:'暂停备份',resume:'继续备份'}
let active=false,epoch=0,context='',timer:ReturnType<typeof setInterval>|undefined
function identity(){return JSON.stringify([dsm.baseUrl,dsm.account,dsm.sid])}
function journalKey(){return 'synolink.hyperbackup.pending:'+JSON.stringify([dsm.baseUrl,dsm.account])}
function client(){const c=new DsmClient(dsm.baseUrl);Object.assign(c,{account:dsm.account,sid:dsm.sid,synoToken:dsm.synoToken,allowInsecure:dsm.allowInsecure,apiInfo:{...dsm.apiInfo}});return c}
function sync(){const next=identity();if(context!==next){epoch++;context=next;pending.value={};rows.value=[];error.value='';notice.value='';detail.value=null;creating.value=false;picker.value=false;loading.value=false;actionBusy.value='';submitting.value=false;shares.value=[];draft.value={name:'NAS 文件备份',share:'',directory:'SynoLink-backup',sources:[],compress:true};try{journal.value=JSON.parse(localStorage.getItem(journalKey())||'null')}catch{journal.value=null}}return next}
function current(captured:string,token:number){return active&&captured===identity()&&token===epoch}
async function refresh(){const captured=sync(),token=epoch;if(loading.value)return;loading.value=true;error.value='';try{await dsm.loadApiInfo();if(!current(captured,token))return;available.value=!!dsm.apiInfo['SYNO.Backup.Task'];if(!available.value){rows.value=[];return}const response=await dsm.hyperBackupTasks();if(!current(captured,token))return;if(!response.success)throw Error(hyperError(response.error?.code));if(!Array.isArray(response.data?.task_list))throw Error('无法识别 Hyper Backup 任务列表');const next=response.data.task_list.map((r:any)=>({id:hyperId(r.task_id),name:String(r.name||'未命名任务'),result:r.last_bkp_result,time:r.last_bkp_time,next:r.next_bkp_time,...hyperState(r),queryError:'',error:''}));rows.value=next;let index=0;await Promise.all([0,1].map(async()=>{while(index<next.length&&current(captured,token)){const row=next[index++];if(!row.id)continue;try{const result=await dsm.hyperBackupStatus(row.id);if(!current(captured,token))return;if(!result.success)throw Error(hyperError(result.error?.code));if(pending.value[row.id]&&pending.value[row.id]!==signature(result.data))delete pending.value[row.id];Object.assign(row,hyperState(result.data),{result:result.data?.last_bkp_result,time:result.data?.last_bkp_time,next:result.data?.next_bkp_time,error:result.data?.last_bkp_error||''})}catch(e){if(current(captured,token)){row.queryError=e instanceof Error?e.message:'状态查询失败';row.actions=[]}}}}));if(current(captured,token)){rows.value=[...next];if(detail.value){detail.value=rows.value.find(t=>t.id===detail.value.id)||null}}}catch(e){if(current(captured,token)){error.value=e instanceof Error?e.message:'读取失败';rows.value=rows.value.map(r=>({...r,actions:[],queryError:'状态待确认'}))}}finally{if(current(captured,token))loading.value=false}}
async function control(row:any,action:HyperAction){if(actionBusy.value||pending.value[row.id])return;const captured=sync();let token=epoch;try{await ElMessageBox.confirm(action==='cancel'?'取消不会删除已存在的备份版本，也不会回滚本次已处理的数据。':action==='backup'?'将在 NAS 上执行此任务的现有备份配置。关闭本软件后，NAS 仍会继续执行。':action==='suspend'?'请求 NAS 暂停当前备份，是否可暂停以 NAS 实际状态为准。':'继续此任务尚未完成的备份。',labels[action],{confirmButtonText:'确认'+labels[action],cancelButtonText:'返回',type:action==='cancel'?'warning':'info'})}catch{return}if(!current(captured,token))return;token=++epoch;loading.value=false;actionBusy.value=row.id;notice.value='';const bound=client();let sent=false;try{const status=await bound.hyperBackupStatus(row.id);if(!current(captured,token))return;if(!status.success)throw Error(hyperError(status.error?.code));const state=hyperState(status.data);if(!state.actions.includes(action))throw Error('任务状态已变化，请刷新后操作');sent=true;pending.value[row.id]=signature(status.data);const result=await bound.hyperBackupRequest('SYNO.Backup.Task',action,{task_id:row.id,...(['cancel','suspend'].includes(action)?{task_state:state.state}:{})},true);if(!current(captured,token))return;if(!result.success){delete pending.value[row.id];throw Error(hyperError(result.error?.code))}notice.value='NAS 已接受'+labels[action]+'请求，实际进度以任务状态为准';await refresh()}catch(e){if(current(captured,token))notice.value=(e instanceof Error?e.message:'请求失败')+(sent?'。提交结果请先刷新核对，不会自动重试。':'')}finally{if(captured===identity())actionBusy.value=''}}
async function clearPending(id:string){const captured=identity();try{await ElMessageBox.confirm('请先在 DSM 确认该操作是否已执行。这里只解除待确认状态，不会重新发送操作。','核对任务状态',{confirmButtonText:'已核对',cancelButtonText:'返回'})}catch{return}if(captured===identity()){delete pending.value[id];void refresh()}}
async function openCreate(){const captured=sync(),token=epoch;if(submitting.value||journal.value)return;creating.value=true;error.value='';shares.value=[];try{const c=client();await c.loadApiInfo();if(!current(captured,token))return;const response=await c.hyperBackupRequest('SYNO.Backup.Storage.Share.Local','list');if(!current(captured,token))return;if(!response.success)throw Error(hyperError(response.error?.code));shares.value=hyperShares(response.data)}catch(e){if(current(captured,token))error.value=e instanceof Error?e.message:'无法读取备份目标'}}
async function create(){if(submitting.value||journal.value)return;const captured=sync(),token=epoch;let data:HyperDraft;try{hyperParams(draft.value);data=JSON.parse(JSON.stringify(draft.value));await ElMessageBox.confirm(`任务：${data.name}\n源目录：${data.sources.join('、')}\n目标：/${data.share}/${data.directory.replace(/\.hbk$/i,'')}.hbk\n创建后手动执行，不启用定时或版本清理。`,'确认创建 Hyper Backup 任务',{confirmButtonText:'创建任务',cancelButtonText:'返回'})}catch(e){if(e instanceof Error)error.value=e.message;return}if(!current(captured,token))return;submitting.value=true;const key=journalKey();const checkpoint=(phase:string,repoId?:string)=>{const record={name:data.name,share:data.share,directory:data.directory,phase,repoId};localStorage.setItem(key,JSON.stringify(record));if(current(captured,token))journal.value=record};try{await createHyperBackup(client(),data,()=>current(captured,token),checkpoint);localStorage.removeItem(key);if(current(captured,token)){journal.value=null;creating.value=false;notice.value='任务已创建，请在列表中手动执行备份';await refresh()}}catch(e){if(current(captured,token))error.value=(e instanceof Error?e.message:'创建失败')+(journal.value?'；可能已建立仓库或任务，请先在 DSM 核对，勿重复提交。':'')}finally{if(captured===identity())submitting.value=false}}
async function acknowledge(){const captured=sync();try{await ElMessageBox.confirm('请先在 DSM Hyper Backup 中核对任务及仓库。这里只清除待核对提示，不会删除 NAS 数据，也不会重新提交创建请求。','已在 DSM 核对',{confirmButtonText:'已核对，清除提示',cancelButtonText:'返回'})}catch{return}if(captured!==identity())return;localStorage.removeItem(journalKey());journal.value=null;void refresh()}
function activate(){if(active)return;active=true;void refresh();timer=setInterval(()=>{if(!document.hidden&&!submitting.value&&!actionBusy.value)void refresh()},10000)}
function stop(){active=false;epoch++;clearInterval(timer);loading.value=false;creating.value=false;picker.value=false;detail.value=null}
onMounted(activate);onActivated(activate);onDeactivated(stop);onBeforeUnmount(stop)
</script>
<template>
<section class="hyper-backup"><header><div><h2>Hyper Backup</h2><p>在 NAS 上创建备份任务，执行备份并跟踪状态。</p></div><div class="hb-actions"><el-button :loading="loading" @click="refresh">刷新</el-button><el-button type="primary" :disabled="!available||submitting||!!journal" @click="openCreate">新建 NAS 备份</el-button></div></header>
<el-alert v-if="error" :title="error" type="warning" :closable="false" show-icon/><el-alert v-if="notice" :title="notice" type="info" :closable="false" show-icon/>
<div v-if="journal" class="hb-pending"><strong>创建结果待核对：{{journal.name}}</strong><p>阶段：{{phaseLabels[journal.phase]||'等待核对'}}<span v-if="journal.repoId"> · 仓库编号 {{journal.repoId}}</span>。请先在 DSM 核对任务与仓库，避免重复创建。</p><el-button :disabled="submitting" @click="acknowledge">我已在 DSM 核对</el-button></div>
<el-empty v-if="!loading&&!rows.length" :description="error?'任务暂时无法读取':available?'暂无 Hyper Backup 任务':'未发现 Hyper Backup 接口，请检查套件和权限'"/>
<div class="hb-grid"><article v-for="row in rows" :key="row.id||row.name" class="hb-card"><div class="hb-title"><h3>{{row.name}}</h3><el-tag>{{row.queryError?'等待查询':row.label}}</el-tag></div><p class="hb-result">最近结果：<el-tag :type="backupResult(row.result).tone">{{backupResult(row.result).label}}</el-tag></p><dl><dt>最近执行</dt><dd>{{displayTime(row.time)}}</dd><dt>下次执行</dt><dd>{{displayTime(row.next)}}</dd></dl><el-progress v-if="row.progress!==null&&row.status!=='none'" :percentage="row.progress"/><p v-if="row.queryError" class="hb-note">{{row.queryError}}</p><p v-if="pending[row.id]" class="hb-note">操作已提交，等待 NAS 状态变化；请勿重复提交。<el-button text :disabled="!!actionBusy" @click="clearPending(row.id)">已核对状态</el-button></p><p v-if="!row.id" class="hb-note">NAS 未返回任务编号，暂时无法执行操作。</p><div class="hb-actions"><el-button v-for="action in row.actions" :key="action" :type="action==='backup'||action==='resume'?'primary':undefined" :disabled="!row.id||!!actionBusy||submitting||loading||!!pending[row.id]" @click="control(row,action)">{{labels[action as HyperAction]}}</el-button><el-button @click="detail=row">查看详情</el-button></div></article></div>
<el-dialog v-model="creating" title="新建 Hyper Backup 任务" width="min(620px,94vw)" :show-close="!submitting" :close-on-click-modal="!submitting" :close-on-press-escape="!submitting"><p class="hb-note">本版支持 NAS 本地／USB 共享文件夹的多版本备份。远程 NAS、云端目标及加密备份请在 DSM 中创建，之后可在这里执行。</p><el-form label-position="top" :disabled="submitting"><el-form-item label="任务名称"><el-input v-model="draft.name" maxlength="32" aria-label="Hyper Backup 任务名称"/></el-form-item><el-form-item label="NAS 源目录"><div class="hb-sources"><el-tag v-for="path in draft.sources" :key="path" :closable="!submitting" @close="draft.sources=draft.sources.filter(p=>p!==path)">{{path}}</el-tag><el-button @click="picker=true">添加源目录</el-button></div></el-form-item><el-form-item label="目标共享文件夹"><el-select v-model="draft.share" placeholder="选择可用目标" aria-label="目标共享文件夹"><el-option v-for="share in shares" :key="share.name" :label="share.name" :value="share.name"/></el-select></el-form-item><el-form-item label="备份目录名"><el-input v-model="draft.directory" maxlength="100" aria-label="备份目录名"><template #append>.hbk</template></el-input></el-form-item><el-checkbox v-model="draft.compress">启用数据压缩</el-checkbox></el-form><p class="hb-note">创建后手动执行；不启用定时、加密或自动删除旧版本。源目录和目标共享文件夹不能相同。备份到同一存储设备不能防范该设备损坏。</p><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template #footer><el-button :disabled="submitting" @click="creating=false">关闭</el-button><el-button type="primary" :loading="submitting" :disabled="!shares.length||!!journal" @click="create">核对并创建</el-button></template></el-dialog>
<FolderPicker v-if="picker" v-model="picker" title="选择 NAS 源目录" @confirm="value=>{if(!draft.sources.includes(value))draft.sources.push(value);picker=false}"/>
<el-dialog :model-value="!!detail" title="备份任务详情" width="min(580px,94vw)" @update:model-value="detail=null"><template v-if="detail"><h3>{{detail.name}}</h3><el-descriptions :column="1" border><el-descriptions-item label="任务编号">{{detail.id||'未返回'}}</el-descriptions-item><el-descriptions-item label="当前状态">{{detail.queryError||detail.label}}</el-descriptions-item><el-descriptions-item label="最近结果">{{backupResult(detail.result).label}}</el-descriptions-item><el-descriptions-item label="最近执行">{{displayTime(detail.time)}}</el-descriptions-item><el-descriptions-item label="下次执行">{{displayTime(detail.next)}}</el-descriptions-item><el-descriptions-item v-if="detail.error" label="NAS 错误">{{detail.error}}</el-descriptions-item></el-descriptions><p class="hb-note">请求被接受不代表备份已经完成。最近结果仅表示上一轮执行结果；当前运行状态以 NAS 返回值为准。</p></template></el-dialog>
</section>
</template>
<style scoped>
.hyper-backup{margin:0 0 24px}header,.hb-title,.hb-actions{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h2{font-size:18px;margin:0}header p,.hb-note,.hb-pending p{font-size:13px;line-height:1.7;color:hsl(var(--muted-foreground))}.hb-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:16px;margin-top:16px}.hb-card,.hb-pending{padding:18px;border:1px solid hsl(var(--border));border-radius:12px;background:hsl(var(--card))}.hb-pending{margin-top:16px}.hb-title h3{font-size:15px;margin:0;overflow-wrap:anywhere}.hb-actions{justify-content:flex-start}.hb-actions .el-button{margin-left:0}.hb-result,dl{font-size:13px}dl{display:grid;grid-template-columns:74px minmax(0,1fr);gap:10px}dt{color:hsl(var(--muted-foreground))}dd{margin:0;overflow-wrap:anywhere}.el-alert{margin-top:12px}.hb-sources{display:flex;gap:8px;flex-wrap:wrap}.hb-sources .el-tag{max-width:100%;height:auto;white-space:normal;overflow-wrap:anywhere}.el-select{width:100%}
</style>
